// Defense-in-depth auth on top of Tailscale's network layer.
//
// Model: a bearer token (generated by `claude-rc setup`). The token guards the
// whole API — reads included, because the session list carries message
// snippets. A `?token=` on any page sets a SameSite=Strict, httpOnly cookie, so
// subsequent fetch + EventSource calls authenticate automatically. SameSite=
// Strict means a cross-site page can't ride the cookie, which is the CSRF
// defence (and works for SSE, which can't send custom headers). When no token
// is configured (e.g. `npm run dev` on loopback) the API is open.
import { timingSafeEqual } from 'node:crypto'

function safeEqual(a: unknown, b: unknown): boolean {
  if (typeof a !== 'string' || typeof b !== 'string') return false
  const ba = Buffer.from(a)
  const bb = Buffer.from(b)
  if (ba.length !== bb.length) return false
  return timingSafeEqual(ba, bb)
}

function presentedToken(event: any): string | null {
  const auth = getHeader(event, 'authorization')
  if (auth && auth.startsWith('Bearer ')) return auth.slice(7)
  const header = getHeader(event, 'x-crc-token')
  if (header) return header
  const cookie = getCookie(event, 'crc_token')
  if (cookie) return cookie
  const q = getQuery(event).token
  if (typeof q === 'string') return q
  return null
}

export default defineEventHandler((event) => {
  const token = process.env.CLAUDE_RC_TOKEN || ''
  if (!token) return // no token configured -> open (loopback dev convenience)

  const url = getRequestURL(event)
  const baseURL = process.env.CLAUDE_RC_BASE_URL || '/'

  // Bootstrap: a correct ?token= on any page sets the cookie for the session.
  const q = getQuery(event).token
  if (typeof q === 'string' && safeEqual(q, token)) {
    setCookie(event, 'crc_token', token, {
      httpOnly: true,
      sameSite: 'strict',
      path: baseURL,
      maxAge: 60 * 60 * 24 * 30,
    })
  }

  // Only the API is guarded; the page and static assets carry no secrets.
  if (!/\/api\//.test(url.pathname)) return

  const presented = presentedToken(event)
  if (!presented || !safeEqual(presented, token)) {
    throw createError({ statusCode: 401, statusMessage: 'unauthorized' })
  }
})
